export interface BitmapGlyph {
  width: number;
  height: number;
  xOffset?: number;
  yOffset: number;
  advance: number;
  rows: number[]; // bitmask per row, bit (width - 1 - col) = x
}

export interface BitmapFont {
  lineHeight: number;
  baseline: number;
  glyphs: Record<string, BitmapGlyph>;
}

const UNICODE_TO_CP1252: Record<string, string> = {
  '\u2018': "'",
  '\u2019': "'",
  '\u02bc': "'",
  '\u201c': '"',
  '\u201d': '"',
  '\u2013': '-',
  '\u2014': '-',
  '\u20ac': String.fromCharCode(128),
  '\u00a0': ' ',
};

function decodeBase64Bytes(b64: string): Uint8Array {
  if (typeof globalThis.atob === 'function') {
    const bin = globalThis.atob(b64);
    const out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) {
      out[i] = bin.charCodeAt(i);
    }
    return out;
  }
  return Uint8Array.from(Buffer.from(b64, 'base64'));
}

function unpackOsrsFont(b64: string, lineHeight: number): BitmapFont {
  const bytes = decodeBase64Bytes(b64);
  const baseline = bytes[0] ?? 12;
  const glyphs: Record<string, BitmapGlyph> = {};

  let pos = 1;
  while (pos + 6 <= bytes.length) {
    const code = bytes[pos++];
    const width = bytes[pos++];
    const height = bytes[pos++];
    const xOffset = bytes[pos++];
    const yOffset = bytes[pos++];
    const advance = bytes[pos++];
    const rowBytes = Math.ceil(width / 8);
    const rows = new Array<number>(height);

    for (let y = 0; y < height; y++) {
      if (rowBytes === 0) {
        rows[y] = 0;
      } else if (rowBytes === 1) {
        rows[y] = bytes[pos++];
      } else {
        rows[y] = (bytes[pos++] << 8) | bytes[pos++];
      }
    }

    glyphs[String.fromCharCode(code)] = {
      width,
      height,
      xOffset,
      yOffset,
      advance,
      rows,
    };
  }

  if (!glyphs[' ']) {
    glyphs[' '] = { width: 0, height: 0, xOffset: 0, yOffset: 0, advance: 4, rows: [] };
  }

  return { lineHeight, baseline, glyphs };
}

// Authentic OSRS rev 242 cache fonts extracted from Index 8 (Sprites) & Index 13 (FontMetrics):
// 494 = p11_full, 495 = p12_full, 496 = b12_full, 497 = q8_full
const FONT_PLAIN_11_B64 =
  '';

const FONT_PLAIN_12_B64 =
  '';

const FONT_BOLD_12_B64 =
  '';

const FONT_QUILL_8_B64 =
  '';

export const FONT_PLAIN_11: BitmapFont = unpackOsrsFont(FONT_PLAIN_11_B64, 11);
export const FONT_PLAIN_12: BitmapFont = unpackOsrsFont(FONT_PLAIN_12_B64, 13);
export const FONT_BOLD_12: BitmapFont = unpackOsrsFont(FONT_BOLD_12_B64, 13);
export const FONT_QUILL_8: BitmapFont = unpackOsrsFont(FONT_QUILL_8_B64, 16);

function lookupGlyph(font: BitmapFont, ch: string): BitmapGlyph {
  const mapped = UNICODE_TO_CP1252[ch] ?? ch;
  return font.glyphs[mapped] ?? font.glyphs[' '];
}

export interface TextRun {
  text: string;
  color: number; // 0xRRGGBB
}

/**
 * Parse OSRS <col=rrggbb>...</col> inline color tags.
 */
export function parseOsrsColoredText(input: string, defaultColor: number): TextRun[] {
  const runs: TextRun[] = [];
  const tagRegex = /<col=([0-9a-fA-F]{3,6})>|<\/col>/g;
  const colorStack: number[] = [defaultColor];
  let lastIndex = 0;

  let match: RegExpExecArray | null;
  while ((match = tagRegex.exec(input)) !== null) {
    if (match.index > lastIndex) {
      runs.push({
        text: input.slice(lastIndex, match.index),
        color: colorStack[colorStack.length - 1],
      });
    }
    if (match[0] === '</col>') {
      if (colorStack.length > 1) colorStack.pop();
    } else {
      const hex = match[1].padStart(6, '0');
      colorStack.push(parseInt(hex, 16) & 0xffffff);
    }
    lastIndex = tagRegex.lastIndex;
  }

  if (lastIndex < input.length) {
    runs.push({
      text: input.slice(lastIndex),
      color: colorStack[colorStack.length - 1],
    });
  }
  return runs;
}

export function measureBitmapText(text: string, font: BitmapFont): number {
  const stripped = text.replace(/<col=[^>]+>|<\/col>/g, '');
  let w = 0;
  for (let i = 0; i < stripped.length; i++) {
    w += lookupGlyph(font, stripped[i]).advance;
  }
  return w;
}

export function wrapBitmapText(text: string, font: BitmapFont, maxWidth: number): string[] {
  const paragraphs = text.split(/\r?\n/);
  const lines: string[] = [];

  for (const para of paragraphs) {
    const words = para.split(/(\s+)/);
    let current = '';
    for (const part of words) {
      if (part === '') continue;
      const candidate = current + part;
      if (current.trim().length > 0 && measureBitmapText(candidate.trimEnd(), font) > maxWidth) {
        lines.push(current.trimEnd());
        current = part.trimStart();
      } else {
        current = candidate;
      }
    }
    lines.push(current.trimEnd());
  }

  return lines.length > 0 ? lines : [''];
}

export function drawBitmapText(
  pixels: Uint8ClampedArray,
  canvasWidth: number,
  canvasHeight: number,
  text: string,
  centerX: number,
  topY: number,
  font: BitmapFont,
  defaultColor: number,
  shadow = false
): void {
  const runs = parseOsrsColoredText(text, defaultColor);
  const totalWidth = measureBitmapText(text, font);
  let cursorX = Math.round(centerX - totalWidth / 2);

  for (const run of runs) {
    const r = (run.color >> 16) & 0xff;
    const g = (run.color >> 8) & 0xff;
    const b = run.color & 0xff;

    for (let i = 0; i < run.text.length; i++) {
      const glyph = lookupGlyph(font, run.text[i]);
      const xOff = glyph.xOffset ?? 0;

      for (let row = 0; row < glyph.height; row++) {
        const mask = glyph.rows[row];
        if (mask === 0) continue;
        const py = topY + glyph.yOffset + row;
        if (py < 0 || py >= canvasHeight) continue;

        for (let col = 0; col < glyph.width; col++) {
          if ((mask & (1 << (glyph.width - 1 - col))) !== 0) {
            const px = cursorX + xOff + col;
            if (shadow && px + 1 < canvasWidth && py + 1 < canvasHeight && px + 1 >= 0 && py + 1 >= 0) {
              const sIdx = ((py + 1) * canvasWidth + (px + 1)) * 4;
              pixels[sIdx] = 0;
              pixels[sIdx + 1] = 0;
              pixels[sIdx + 2] = 0;
              pixels[sIdx + 3] = 255;
            }
            if (px >= 0 && px < canvasWidth) {
              const idx = (py * canvasWidth + px) * 4;
              pixels[idx] = r;
              pixels[idx + 1] = g;
              pixels[idx + 2] = b;
              pixels[idx + 3] = 255;
            }
          }
        }
      }

      cursorX += glyph.advance;
    }
  }
}
